class Solution {
public:
    int eatenApples(vector<int>& apples, vector<int>& days) {
        priority_queue<pair<long long, long long>,
                       vector<pair<long long, long long>>, greater<>> pq;
        int n = apples.size();
        vector<int> grow;
        for (int i = 0; i < n; i++)
            if (apples[i] > 0) grow.push_back(i);
        long long eaten = 0, day = 0;
        size_t gp = 0;
        while (day < n || !pq.empty()) {
            while (gp < grow.size() && grow[gp] <= day) {
                int i = grow[gp++];
                pq.push({(long long)i + days[i], (long long)apples[i]});
            }
            while (!pq.empty() && pq.top().first <= day) pq.pop();
            if (!pq.empty()) {
                auto [rot, cnt] = pq.top();
                pq.pop();
                long long limit = gp < grow.size() ? grow[gp] : rot;
                long long eat = min({cnt, rot - day, limit - day});
                eaten += eat;
                day += eat;
                if (cnt > eat) pq.push({rot, cnt - eat});
            } else {
                day = gp < grow.size() ? grow[gp] : day + 1;
            }
        }
        return (int)eaten;
    }
};

