class Solution {
    public int eatenApples(int[] apples, int[] days) {
        PriorityQueue<long[]> pq =
                new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        int n = apples.length;
        List<Integer> grow = new ArrayList<>();
        for (int i = 0; i < n; i++)
            if (apples[i] > 0) grow.add(i);
        long eaten = 0, day = 0;
        int gp = 0;
        while (day < n || !pq.isEmpty()) {
            while (gp < grow.size() && grow.get(gp) <= day) {
                int i = grow.get(gp++);
                pq.offer(new long[]{(long) i + days[i], apples[i]});
            }
            while (!pq.isEmpty() && pq.peek()[0] <= day) pq.poll();
            if (!pq.isEmpty()) {
                long[] top = pq.poll();
                long limit = gp < grow.size() ? grow.get(gp) : top[0];
                long eat = Math.min(top[1], Math.min(top[0] - day, limit - day));
                eaten += eat;
                day += eat;
                if (top[1] > eat) pq.offer(new long[]{top[0], top[1] - eat});
            } else {
                day = gp < grow.size() ? grow.get(gp) : day + 1;
            }
        }
        return (int) eaten;
    }
};

